import thebetweenlands.common.registries.LootTableRegistry;
import thebetweenlands.common.registries.SoundRegistry;

public class EntitySiltCrab extends EntityMob implements IEntityBL {

	protected EntityAIAttackMelee aiAttack;
	protected EntityAIAvoidEntity<EntityPlayer> aiRunAway;
	protected EntityAINearestAttackableTarget<EntityPlayer> aiTarget;

	protected int aggroCooldown = 200;
	protected boolean canAttack = false;

	private static final DataParameter<ItemStack> TRIM_ITEM_1 = EntityDataManager.createKey(EntitySiltCrab.class, DataSerializers.ITEM_STACK);
	private static final DataParameter<ItemStack> TRIM_ITEM_2 = EntityDataManager.createKey(EntitySiltCrab.class, DataSerializers.ITEM_STACK);
	private static final DataParameter<ItemStack> TRIM_ITEM_3 = EntityDataManager.createKey(EntitySiltCrab.class, DataSerializers.ITEM_STACK);

	public EntitySiltCrab(World world) {
		super(world);
		this.setSize(0.8F, 0.6F);
		this.stepHeight = 2;
	}

    @Override
    protected SoundEvent getHurtSound(DamageSource source) {
        return SoundRegistry.CRUNCH;
    }

    @Override
    protected SoundEvent getDeathSound() {
        return SoundRegistry.CRUNCH;
    }

	@Override
	protected void entityInit() {
		super.entityInit();
		dataManager.register(TRIM_ITEM_1, ItemStack.EMPTY);
		dataManager.register(TRIM_ITEM_2, ItemStack.EMPTY);
		dataManager.register(TRIM_ITEM_3, ItemStack.EMPTY);
	}

	@Override
	protected void initEntityAI() {
		this.aiAttack = new EntityAIAttackMelee(this, 1.0D, true);
		this.aiRunAway = new EntityAIAvoidEntity<EntityPlayer>(this, EntityPlayer.class, 10.0F, 0.7D, 0.7D);
		this.aiTarget =  new EntityAINearestAttackableTarget<EntityPlayer>(this, EntityPlayer.class, true);

		this.tasks.addTask(0, this.aiAttack);
		this.tasks.addTask(1, this.aiRunAway);
		this.tasks.addTask(2, new EntityAIWander(this, 1.0D));
		this.tasks.addTask(3, new EntityAILookIdle(this));
		this.tasks.addTask(4, new EntityAIAttackOnCollide(this));

		this.targetTasks.addTask(0, new EntityAIHurtByTarget(this, true));
		this.targetTasks.addTask(1, this.aiTarget);
	}

	@Override
	protected void applyEntityAttributes() {
		super.applyEntityAttributes();
		this.getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).setBaseValue(0.35D);
		this.getEntityAttribute(SharedMonsterAttributes.MAX_HEALTH).setBaseValue(8.0D);
		this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).setBaseValue(3.0D);
		this.getEntityAttribute(SharedMonsterAttributes.FOLLOW_RANGE).setBaseValue(16.0D);
	}

	public void setItem1(ItemStack itemStack) {
		dataManager.set(TRIM_ITEM_1, itemStack);
	}

	public ItemStack getItem1() {
		return dataManager.get(TRIM_ITEM_1);
	}

	public void setItem2(ItemStack itemStack) {
		dataManager.set(TRIM_ITEM_2, itemStack);
	}

	public ItemStack getItem2() {
		return dataManager.get(TRIM_ITEM_2);
	}

	public void setItem3(ItemStack itemStack) {
		dataManager.set(TRIM_ITEM_3, itemStack);
	}

	public ItemStack getItem3() {
		return dataManager.get(TRIM_ITEM_3);
	}

	@Override
	public void writeEntityToNBT(NBTTagCompound nbt) {
		super.writeEntityToNBT(nbt);

		NBTTagCompound item1 = new NBTTagCompound();
		getItem1().writeToNBT(item1);
		nbt.setTag("item1", item1);

		NBTTagCompound item2 = new NBTTagCompound();
		getItem2().writeToNBT(item2);
		nbt.setTag("item2", item2);

		NBTTagCompound item3 = new NBTTagCompound();
		getItem3().writeToNBT(item3);
		nbt.setTag("item3", item3);
	}

	@Override
	public void readEntityFromNBT(NBTTagCompound nbt) {
		super.readEntityFromNBT(nbt);

		NBTBase item1 = nbt.getTag("item1");
		ItemStack stack1 = ItemStack.EMPTY;
		if(item1 instanceof NBTTagCompound)
			stack1 = new ItemStack((NBTTagCompound) item1);
		setItem1(stack1);

		NBTBase item2 = nbt.getTag("item2");
		ItemStack stack2 = ItemStack.EMPTY;
		if(item2 instanceof NBTTagCompound)
			stack2 = new ItemStack((NBTTagCompound) item2);
		setItem2(stack2);

		NBTBase item3 = nbt.getTag("item3");
		ItemStack stack3 = ItemStack.EMPTY;
		if(item3 instanceof NBTTagCompound)
			stack3 = new ItemStack((NBTTagCompound) item3);
		setItem3(stack3);

		//Giving legacy silt crabs items
		if(!this.world.isRemote && item1 == null && item2 == null && item3 == null) {
			this.randomizeSiltCrabProperties();
		}
	}

	@Nullable
	@Override
	public IEntityLivingData onInitialSpawn(DifficultyInstance difficulty, @Nullable IEntityLivingData livingdata) {
		if(!getEntityWorld().isRemote) {
			this.randomizeSiltCrabProperties();
		}
		return super.onInitialSpawn(difficulty, livingdata);
	}

	public void randomizeSiltCrabProperties() {
		setItem1(getPartFromLootTable(LootTableRegistry.SILT_CRAB_TRIM_1));
		setItem2(getPartFromLootTable(LootTableRegistry.SILT_CRAB_TRIM_2));
		setItem3(getPartFromLootTable(LootTableRegistry.SILT_CRAB_TRIM_3));
	}

	public ItemStack getPartFromLootTable(ResourceLocation lootTableIn) {
		if(this.world instanceof WorldServer) {
			LootTable lootTable = this.world.getLootTableManager().getLootTableFromLocation(lootTableIn);
			if (lootTable != null) {
				LootContext.Builder lootBuilder = (new LootContext.Builder((WorldServer) this.world).withLootedEntity(this));
				List<ItemStack> loot = lootTable.generateLootForPools(this.world.rand, lootBuilder.build());
				if (!loot.isEmpty()) 
					return loot.get(0);
			}
		}
		return ItemStack.EMPTY; // to stop null;
	}

	@Override
	public int getMaxSpawnedInChunk() {
		return 5;
	}

	@Override
	protected void playStepSound(BlockPos pos, Block blockIn) {
		this.playSound(SoundEvents.ENTITY_SPIDER_STEP, 0.15F, 1.0F);
	}

	@Override
	public void onUpdate() {
		super.onUpdate();

		if (!this.world.isRemote) {
			if (this.aggroCooldown == 200 && !this.canAttack) {
				this.tasks.removeTask(this.aiRunAway);
				this.tasks.addTask(0, this.aiAttack);
				this.targetTasks.addTask(1, this.aiTarget);
				this.canAttack = true;
			}

			if (this.aggroCooldown == 0 && this.canAttack) {
				this.tasks.removeTask(this.aiAttack);
				this.targetTasks.removeTask(this.aiTarget);
				this.tasks.addTask(1, this.aiRunAway);
				this.canAttack = false;
			}

			if (this.aggroCooldown < 201)
				this.aggroCooldown++;
		}
	}

	@Override
	public boolean attackEntityFrom(DamageSource source, float damage) {
		return !source.equals(DamageSource.DROWN) && super.attackEntityFrom(source, damage);
	}

	@Override
	public void onCollideWithPlayer(EntityPlayer player) {
		if (!this.world.isRemote && getDistance(player) <= 1.5F && this.canAttack) {
			this.aggroCooldown = 0;
		}
	}

	@Override
	public boolean attackEntityAsMob(Entity entityIn) {
		boolean attacked;
		if(attacked = super.attackEntityAsMob(entityIn)) {
			this.playSound(SoundRegistry.CRAB_SNIP, 1, 1);
		}
		return attacked;
	}

	@Override
	protected boolean canDespawn() {
		return false;
	}

	@Override
	protected ResourceLocation getLootTable() {
		return LootTableRegistry.SILT_CRAB;
	}

	@Override
    public float getBlockPathWeight(BlockPos pos) {
        return 0.5F;
    }

    @Override
    protected boolean isValidLightLevel() {
    	return true;
    }

    public boolean lureToCrabPot(BlockPos pos) {
    	return this.getNavigator().tryMoveToXYZ(pos.getX() + 0.5D, pos.getY() + 1D, pos.getZ() + 0.5D, 1D);
    }

    @Nullable
    public ItemMob getCrabPotItem() {
    	return ItemRegistry.SILT_CRAB;
    }
}

package thebetweenlands.common.inventory.container;

import java.util.ArrayList;
import java.util.List;

import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.entity.player.InventoryPlayer;
import net.minecraft.inventory.Container;
import net.minecraft.inventory.IInventory;
import net.minecraft.inventory.Slot;
import net.minecraft.item.ItemStack;
import net.minecraft.util.SoundCategory;
import net.minecraft.util.math.BlockPos;
import thebetweenlands.common.inventory.slot.SlotOutput;
import thebetweenlands.common.inventory.slot.SlotRestrictionListNoMeta;
import thebetweenlands.common.inventory.slot.SlotRestrictionNoMeta;
import thebetweenlands.common.item.misc.ItemMob;
import thebetweenlands.common.registries.AdvancementCriterionRegistry;
import thebetweenlands.common.registries.ItemRegistry;
import thebetweenlands.common.registries.SoundRegistry;
import thebetweenlands.common.tile.TileEntityFishTrimmingTable;

public class ContainerFishTrimmingTable extends Container {

	private final EntityPlayer player;
	public List<ItemStack> acceptedItems = new ArrayList<>();

	public ItemStack axe = new ItemStack(ItemRegistry.BONE_AXE);
	public TileEntityFishTrimmingTable trimmingTable;

	private class SlotTrimmingOutput extends SlotOutput {
		private int prevCount;

		public SlotTrimmingOutput(IInventory inventoryIn, int index, int xPosition, int yPosition, Container container) {
			super(inventoryIn, index, xPosition, yPosition, container);
			this.updateCount();
		}

		private void updateCount() {
			this.prevCount = this.getStack().getCount();
		}

		@Override
		public void onSlotChanged() {
			super.onSlotChanged();

			if(!trimmingTable.getStackInSlot(4).isEmpty()) {
				int index = this.getSlotIndex();

				if(index == 1 || index == 2 || index == 3) {
					int removed = Math.max(0, this.prevCount - this.getStack().getCount());

					if(removed > 0) {
						trimmingTable.getStackInSlot(4).shrink(removed);
						trimmingTable.markDirty();

						ContainerFishTrimmingTable.this.onCraftMatrixChanged(trimmingTable);
					}
				}
			}

			this.updateCount();
		}

		@Override
		public ItemStack onTake(EntityPlayer thePlayer, ItemStack stack) {
			if(thePlayer instanceof EntityPlayerMP) {
				AdvancementCriterionRegistry.TRIM_FISH.trigger((EntityPlayerMP) thePlayer);
			}

			if(this.getSlotIndex() == 4) {
				trimmingTable.setInventorySlotContents(1, ItemStack.EMPTY);
				trimmingTable.setInventorySlotContents(2, ItemStack.EMPTY);
				trimmingTable.setInventorySlotContents(3, ItemStack.EMPTY);
				ContainerFishTrimmingTable.this.onCraftMatrixChanged(trimmingTable);
			}

			return super.onTake(thePlayer, stack);
		}
	}

	public ContainerFishTrimmingTable(EntityPlayer player, TileEntityFishTrimmingTable tile) {
		InventoryPlayer playerInventory = player.inventory;
		this.player = player;
		trimmingTable = tile;
		acceptedItems.add(new ItemStack(ItemRegistry.ANADIA));
		acceptedItems.add(new ItemStack(ItemRegistry.SILT_CRAB));
		acceptedItems.add(new ItemStack(ItemRegistry.BUBBLER_CRAB));

		//input
		addSlotToContainer(new SlotRestrictionListNoMeta(trimmingTable, 0, 80, 27, getItemList(), 1, this));

		//output
		addSlotToContainer(new SlotTrimmingOutput(trimmingTable, 1, 44, 77, this));
		addSlotToContainer(new SlotTrimmingOutput(trimmingTable, 2, 80, 77, this));
		addSlotToContainer(new SlotTrimmingOutput(trimmingTable, 3, 116, 77, this));
		addSlotToContainer(new SlotTrimmingOutput(trimmingTable, 4, 8, 113, this));

		//tool
		addSlotToContainer(new SlotRestrictionNoMeta(trimmingTable, 5, 152, 113, axe, 1));

		for (int l = 0; l < 3; ++l)
			for (int j1 = 0; j1 < 9; ++j1)
				this.addSlotToContainer(new Slot(playerInventory, j1 + (l + 1) * 9, 8 + j1 * 18, 145 + l * 18));

		for (int i1 = 0; i1 < 9; ++i1)
			this.addSlotToContainer(new Slot(playerInventory, i1, 8 + i1 * 18, 203));
	}

	@Override
	public ItemStack transferStackInSlot(EntityPlayer player, int slotIndex) {
		ItemStack stack = ItemStack.EMPTY;
		Slot slot = inventorySlots.get(slotIndex);

		if (slot != null && slot.getHasStack()) {
			ItemStack stack1 = slot.getStack();
			stack = stack1.copy();

			if (slotIndex > 5) {
				if ((stack1.getItem() == ItemRegistry.ANADIA || stack1.getItem() == ItemRegistry.SILT_CRAB || stack1.getItem() == ItemRegistry.BUBBLER_CRAB) && ((ItemMob) stack1.getItem()).hasEntityData(stack1)) {
					if (!this.mergeItemStack(stack1, 0, 1, false))
						return ItemStack.EMPTY;
				}

				if (stack1.getItem() == ItemRegistry.BONE_AXE) {
					if (!this.mergeItemStack(stack1, 5, 6, false))
						return ItemStack.EMPTY;
				}

				if (!this.mergeItemStack(stack1, 1, 5, false))
					return ItemStack.EMPTY;

			} else if (!mergeItemStack(stack1, 6, inventorySlots.size(), false))
				return ItemStack.EMPTY;

			if (stack1.isEmpty())
				slot.putStack(ItemStack.EMPTY);
			else
				slot.onSlotChanged();

			if (stack1.getCount() == stack.getCount())
				return ItemStack.EMPTY;

			ItemStack stack2 = slot.onTake(player, stack1);

			if (slotIndex == 1 || slotIndex == 2 || slotIndex == 3 || slotIndex == 4)
				player.dropItem(stack2, false);
		}

		return stack;
	}

	@Override
	public boolean canInteractWith(EntityPlayer playerIn) {
		BlockPos pos = this.trimmingTable.getPos();
		if(playerIn.world.getTileEntity(pos) != this.trimmingTable) {
			return false;
		} else {
			return playerIn.getDistanceSq(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D) <= 64.0D;
		}
	}

	public List<ItemStack> getItemList() {
		return acceptedItems;
	}

	public void chop(EntityPlayerMP player) {
		if((this.trimmingTable.hasAnadia() || this.trimmingTable.hasSiltCrab() || this.trimmingTable.hasBubblerCrab()) && this.trimmingTable.hasChopper() && this.trimmingTable.allResultSlotsEmpty()) {

			// set slot contents 1, 2, 3 to butcher items and 4 to guts
			int numItems = 0;
			for(int i = 1; i <= 4; i++) {
				ItemStack result = this.trimmingTable.getSlotResult(i, numItems);
				numItems += result.getCount();
				this.getSlot(i).putStack(result);
			}

			// damage axe
			this.trimmingTable.getStackInSlot(5).damageItem(1, player);

			// set slot contents 0 to empty last so logic works in order
			this.trimmingTable.setInventorySlotContents(0, this.trimmingTable.getSlotResult(0, 0));

			this.onCraftMatrixChanged(trimmingTable);

			player.world.playSound(null, this.trimmingTable.getPos(), SoundRegistry.FISH_CHOP, SoundCategory.BLOCKS, 1F, 1F);
		}
	}
}

package thebetweenlands.common.item.misc;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.Function;

import javax.annotation.Nullable;

import net.minecraft.client.resources.I18n;
import net.minecraft.client.util.ITooltipFlag;
import net.minecraft.creativetab.CreativeTabs;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityList;
import net.minecraft.entity.EntityLiving;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.monster.IMob;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumActionResult;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.EnumHand;
import net.minecraft.util.NonNullList;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.EnumDifficulty;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.client.tab.BLCreativeTabs;
import thebetweenlands.util.NBTHelper;

public class ItemMob extends Item {
	private static final Map<Class<? extends Entity>, Function<Entity, EnumActionResult>> SPAWN_HANDLERS = new HashMap<>();

	public static final Function<Entity, EnumActionResult> DEFAULT_SPAWN_HANDLER = entity -> {
		if((entity.world.getDifficulty() != EnumDifficulty.PEACEFUL || entity instanceof IMob == false) && entity.world.getCollisionBoxes(entity, entity.getEntityBoundingBox()).isEmpty()) {
			return EnumActionResult.SUCCESS;
		}
		return EnumActionResult.FAIL;
	};

	private final Class<? extends Entity> defaultMob;
	private final Consumer<Entity> defaultMobSetter;

	/**
	 * @param maxStackSize Max stack size of the item. If this is > 1 then only the entity's ID and no additional NBT is stored.
	 * @param defaultMob Default mob type of this item
	 * @param defaultMobSetter Sets the properties of the default mob
	 */
	@SuppressWarnings("unchecked")
	public <T extends Entity> ItemMob(int maxStackSize, @Nullable Class<T> defaultMob, @Nullable Consumer<T> defaultMobSetter) {
		this.maxStackSize = maxStackSize;
		this.defaultMob = defaultMob;
		this.defaultMobSetter = (Consumer<Entity>) defaultMobSetter;
		this.setCreativeTab(BLCreativeTabs.ITEMS);
	}

	public static void registerSpawnHandler(Class<? extends Entity> cls, Function<Entity, EnumActionResult> handler) {
		Function<Entity, EnumActionResult> current = SPAWN_HANDLERS.get(cls);
		if(current != null) {
			SPAWN_HANDLERS.put(cls, entity -> {
				EnumActionResult result1 = handler.apply(entity);
				if(result1 == EnumActionResult.SUCCESS || result1 == EnumActionResult.FAIL) {
					return result1;
				}
				EnumActionResult result2 = current.apply(entity);
				if(result2 == EnumActionResult.SUCCESS || result2 == EnumActionResult.FAIL) {
					return result2;
				}
				return EnumActionResult.PASS;
			});
		} else {
			SPAWN_HANDLERS.put(cls, handler);
		}
	}

	public ItemStack capture(Class<? extends Entity> cls) {
		return this.capture(cls, null);
	}

	public ItemStack capture(Class<? extends Entity> cls, @Nullable NBTTagCompound nbt) {
		ResourceLocation id = EntityList.getKey(cls);
		if(id != null) {
			if(nbt == null) {
				nbt = new NBTTagCompound();
			}
			nbt.setString("id", id.toString());

			ItemStack stack = new ItemStack(this);

			stack.setTagInfo("Entity", nbt);

			return stack;
		}

		return ItemStack.EMPTY;
	}

	public ItemStack capture(Entity entity) {
		NBTTagCompound nbt = new NBTTagCompound();

		if(this.maxStackSize == 1) {
			entity.writeToNBTOptional(nbt);
		} else {
			NBTTagCompound entityNbt = new NBTTagCompound();
			if(entity.writeToNBTOptional(entityNbt) && entityNbt.hasKey("id", Constants.NBT.TAG_STRING)) {
				nbt.setString("id", entityNbt.getString("id"));
			}
		}

		if(!nbt.isEmpty()) {
			ItemStack stack = new ItemStack(this);

			stack.setTagInfo("Entity", nbt);

			if(entity.hasCustomName()) {
				stack.setStackDisplayName(entity.getCustomNameTag());
			}

			return stack;
		}

		return ItemStack.EMPTY;
	}

	public boolean isCapturedEntity(ItemStack stack, Class<? extends Entity> cls) {
		if(stack.getItem() != this) {
			return false;
		}

		NBTTagCompound nbt = stack.getTagCompound();

		if(nbt != null && nbt.hasKey("Entity", Constants.NBT.TAG_COMPOUND)) {
			NBTTagCompound entityNbt = nbt.getCompoundTag("Entity");

			if(entityNbt.hasKey("id", Constants.NBT.TAG_STRING)) {
				Class<? extends Entity> entityCls = EntityList.getClass(new ResourceLocation(entityNbt.getString("id")));
				return entityCls != null && cls.isAssignableFrom(entityCls);
			}
		}

		return this.defaultMob != null && cls.isAssignableFrom(this.defaultMob);
	}

	public boolean hasEntityData(ItemStack stack) {
		NBTTagCompound nbt = stack.getTagCompound();
		return nbt != null && nbt.hasKey("Entity", Constants.NBT.TAG_COMPOUND);
	}

	@Nullable
	public NBTTagCompound getEntityData(ItemStack stack) {
		NBTTagCompound nbt = stack.getTagCompound();
		if(nbt != null) {
			return nbt.getCompoundTag("Entity");
		}
		return null;
	}

	public void setEntityData(ItemStack stack, @Nullable NBTTagCompound entityData) {
		NBTTagCompound nbt = NBTHelper.getStackNBTSafe(stack);
		if(entityData == null) {
			nbt.removeTag("Entity");
		} else {
			nbt.setTag("Entity", entityData);
		}
	}

	@Nullable
	public ResourceLocation getCapturedEntityId(ItemStack stack) {
		if(stack.getItem() instanceof ItemMob == false) {
			return null;
		}

		if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND)) {
			NBTTagCompound entityNbt = stack.getTagCompound().getCompoundTag("Entity");

			if(entityNbt.hasKey("id", Constants.NBT.TAG_STRING)) {
				return new ResourceLocation(entityNbt.getString("id"));
			}
		}

		if(this.defaultMob != null) {
			return EntityList.getKey(this.defaultMob);
		}

		return null;
	}

	protected static void handleOnInitialSpawn(Entity entity) {
		if(!entity.world.isRemote && entity instanceof EntityLiving) {
			((EntityLiving) entity).onInitialSpawn(entity.world.getDifficultyForLocation(new BlockPos(entity)), null);
		}
	}

	@Nullable
	public Entity createCapturedEntity(World world, double x, double y, double z, ItemStack stack, boolean allowOnInitialSpawn) {
		return this.createCapturedEntity(world, x, y, z, stack, entity -> {
			if(allowOnInitialSpawn) {
				handleOnInitialSpawn(entity);
			}
		}); 
	}

	@Nullable
	public Entity createCapturedEntity(World world, double x, double y, double z, ItemStack stack, @Nullable Consumer<Entity> onNewEntityCreated) {
		if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND)) {
			return this.createCapturedEntityFromNBT(world, x, y, z, stack.getTagCompound().getCompoundTag("Entity"));
		}

		if(this.defaultMob != null) {
			ResourceLocation id = EntityList.getKey(this.defaultMob);
			if(id != null) {
				Entity entity = EntityList.createEntityByIDFromName(id, world);
				if(entity != null) {
					entity.setLocationAndAngles(x, y, z, world.rand.nextFloat() * 360.0f, 0);
					if(this.defaultMobSetter != null) {
						this.defaultMobSetter.accept(entity);
					}
					if(onNewEntityCreated != null) {
						onNewEntityCreated.accept(entity);
					}
					return entity;
				}
			}
		}

		return null;
	}

	@Nullable
	protected Entity createCapturedEntityFromNBT(World world, double x, double y, double z, NBTTagCompound nbt) {
		Entity entity = EntityList.createEntityFromNBT(nbt, world);

		if(entity != null) {
			entity.setUniqueId(UUID.randomUUID());
			entity.setLocationAndAngles(x, y, z, world.rand.nextFloat() * 360.0f, 0);
			entity.motionX = entity.motionY = entity.motionZ = 0;
			return entity;
		}

		return null;
	}

	@Override
	public void getSubItems(CreativeTabs tab, NonNullList<ItemStack> items) {
		if(this.defaultMob != null && this.isInCreativeTab(tab)) {
			items.add(new ItemStack(this));
		}
	}

	@Override
	public EnumActionResult onItemUse(EntityPlayer player, World world, BlockPos pos, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ) {
		ItemStack stack = player.getHeldItem(hand);

		final AtomicBoolean isNewEntity = new AtomicBoolean();

		Entity entity = this.createCapturedEntity(world, pos.getX() + hitX, pos.getY() + hitY, pos.getZ() + hitZ, stack, e -> isNewEntity.set(true));
		if(entity != null) {
			if(facing.getXOffset() != 0) {
				entity.setPosition(entity.posX + facing.getXOffset() * entity.width * 0.5f, entity.posY, entity.posZ);
			}
			if(facing.getYOffset() < 0) {
				entity.setPosition(entity.posX, entity.posY - entity.height, entity.posZ);
			}
			if(facing.getZOffset() != 0) {
				entity.setPosition(entity.posX, entity.posY, entity.posZ + facing.getZOffset() * entity.width * 0.5f);
			}

			Function<Entity, EnumActionResult> spawnHandler = SPAWN_HANDLERS.get(entity.getClass());
			if(spawnHandler == null) {
				spawnHandler = DEFAULT_SPAWN_HANDLER;
			}

			EnumActionResult result = spawnHandler.apply(entity);

			if(result == EnumActionResult.SUCCESS) {
				result = this.spawnCapturedEntity(player, world, pos, hand, facing, hitX, hitY, hitZ, entity, isNewEntity.get());

				if(result == EnumActionResult.SUCCESS) {
					if(!world.isRemote) {
						stack.shrink(1);
					}
				}
			}

			return result;
		}

		return EnumActionResult.PASS;
	}

	protected EnumActionResult spawnCapturedEntity(EntityPlayer player, World world, BlockPos pos, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ, Entity entity, boolean isNewEntity) {
		if(!world.isRemote) {
			if(isNewEntity) {
				handleOnInitialSpawn(entity);
			}

			world.spawnEntity(entity);

			if(entity instanceof EntityLiving) {
				((EntityLiving) entity).playLivingSound();
			}
		}

		return EnumActionResult.SUCCESS;
	}

	public void onCapturedByPlayer(EntityPlayer player, EnumHand hand, ItemStack captured, EntityLivingBase entity) {

	}

	@Override
	public String getTranslationKey(ItemStack stack) {
		ResourceLocation id = this.getCapturedEntityId(stack);
		if(id != null) {
			return "entity." + id.getNamespace() + "." + id.getPath();
		}
		return super.getTranslationKey(stack);
	}

	@Override
	public boolean hasCustomProperties() {
		return true;
	}

	@SideOnly(Side.CLIENT)
	@Override
	public void addInformation(ItemStack stack, World worldIn, List<String> tooltip, ITooltipFlag flagIn) {
		if(worldIn != null) {
			Entity entity = this.createCapturedEntity(worldIn, 0, 0, 0, stack, false);
			if(entity instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) entity;
				tooltip.add(I18n.format("tooltip.bl.item_mob.health", MathHelper.ceil(living.getHealth() / 2), MathHelper.ceil(living.getMaxHealth() / 2)));
			}
		}
	}
}

package thebetweenlands.common.item.misc;

import java.util.List;
import java.util.function.Consumer;

import javax.annotation.Nullable;

import net.minecraft.client.Minecraft;
import net.minecraft.client.resources.I18n;
import net.minecraft.client.util.ITooltipFlag;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.SharedMonsterAttributes;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumActionResult;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.EnumHand;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.api.capability.IRotSmellCapability;
import thebetweenlands.client.tab.BLCreativeTabs;
import thebetweenlands.common.entity.EntityFishingTackleBoxSeat;
import thebetweenlands.common.entity.mobs.EntityAnadia;
import thebetweenlands.common.entity.mobs.EntitySwampHag;
import thebetweenlands.common.item.ITintedItem;
import thebetweenlands.common.registries.CapabilityRegistry;

public class ItemMobAnadia extends ItemMob implements ITintedItem {

	public <T extends Entity> ItemMobAnadia(int maxStackSize, @Nullable Class<T> defaultMob, @Nullable Consumer<T> defaultMobSetter) {
		super(1, defaultMob, defaultMobSetter);
		this.setCreativeTab(BLCreativeTabs.ITEMS);
	}

	public int getDecayTime(ItemStack stack) {
		return 24000; // 20 minutes
	}

	@Override
    public boolean hitEntity(ItemStack stack, EntityLivingBase target, EntityLivingBase attacker) {
		if (!attacker.getEntityWorld().isRemote) {
			if (target instanceof EntitySwampHag && !target.isRiding() && attacker instanceof EntityPlayer) {
				if (attacker.getEntityWorld().getBlockState(target.getPosition().down()).getMaterial().blocksMovement()) {
					EntityFishingTackleBoxSeat entitySeat = new EntityFishingTackleBoxSeat(attacker.getEntityWorld(), true);
					entitySeat.setPosition(target.posX, target.posY - 0.55D, target.posZ);
					attacker.getEntityWorld().spawnEntity(entitySeat);
					target.startRiding(entitySeat, true);
				}
			}
		}
		return false;
	}

	@Override
	protected EnumActionResult spawnCapturedEntity(EntityPlayer player, World world, BlockPos pos, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ, Entity entity, boolean isNewEntity) {
		if(entity instanceof EntityAnadia && !((EntityAnadia) entity).getFishColour().isAlive()) {
			return EnumActionResult.PASS;
		}
		return super.spawnCapturedEntity(player, world, pos, hand, facing, hitX, hitY, hitZ, entity, isNewEntity);
	}

	public void setRotten(World world, ItemStack stack, boolean rotten) {
		if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND)) {
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") != 0) {
				if(rotten) {
					stack.getTagCompound().getCompoundTag("Entity").setLong("rottingTime", world.getTotalWorldTime());
				} else {
					stack.getTagCompound().getCompoundTag("Entity").setLong("rottingTime", world.getTotalWorldTime() + this.getDecayTime(stack));
				}
			}
		}
	}

	public boolean isRotten(World world, ItemStack stack) {
		if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND))
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") != 0)
				if(stack.getTagCompound().getCompoundTag("Entity").hasKey("rottingTime")) {
					long timeFished = stack.getTagCompound().getCompoundTag("Entity").getLong("rottingTime");
					long worldTime = world.getTotalWorldTime();
					return timeFished - worldTime <= 0;
		}
		return false;
	}

	@Override
    public void onUpdate(ItemStack stack, World world, Entity entity, int itemSlot, boolean isSelected) {
		if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND))
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") != 0 && stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") != 1)
				if(stack.getTagCompound().getCompoundTag("Entity").hasKey("rottingTime"))
					if(world.getTotalWorldTime() >= stack.getTagCompound().getCompoundTag("Entity").getLong("rottingTime"))
						stack.getTagCompound().getCompoundTag("Entity").setByte("fishColour", (byte) 1);

		if(isRotten(world, stack) & entity instanceof EntityPlayer) {
			if(!world.isRemote)
				addSmell((EntityLivingBase) entity);
		}
    }

	public static void addSmell(EntityLivingBase entity) {
		IRotSmellCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_ROT_SMELL, null);
		if(cap != null) {
			if(!cap.isSmellingBad()) {
				cap.setSmellingBad(Math.max(cap.getRemainingSmellyTicks(), 24000));
			}
		}
	}

	@Override
	public void onCapturedByPlayer(EntityPlayer player, EnumHand hand, ItemStack stack, EntityLivingBase entity) {
		if(!player.getEntityWorld().isRemote) {
			if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND))
				stack.getTagCompound().getCompoundTag("Entity").setLong("rottingTime", player.getEntityWorld().getTotalWorldTime() + this.getDecayTime(stack));
			if (entity instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) entity;
				if (living instanceof EntityAnadia) {
					if (((EntityAnadia) living).isBeingRidden())
						((EntityAnadia) living).removePassengers();
				}
			}
		}
	}

	@SideOnly(Side.CLIENT)
	@Override
	public void addInformation(ItemStack stack, World worldIn, List<String> tooltip, ITooltipFlag flagIn) {
		if(worldIn != null) {
			Entity entity = this.createCapturedEntity(worldIn, 0, 0, 0, stack, false);
			if(entity instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) entity;
				if (living instanceof EntityAnadia) {
					NBTTagCompound entityNbt = this.getEntityData(stack);

					if(entityNbt != null) {
						tooltip.add(I18n.format(living.getName()));

						if(entityNbt.getByte("fishColour") != 0) {
							if(entityNbt.hasKey("rottingTime")) {
								long rottingTime = entityNbt.getLong("rottingTime");
								if(rottingTime - worldIn.getTotalWorldTime() > 19200)
									tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.rotting_1"));
								else if(rottingTime - worldIn.getTotalWorldTime() <= 19200 && rottingTime - worldIn.getTotalWorldTime() > 14400)
									tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.rotting_2"));
								else if(rottingTime - worldIn.getTotalWorldTime() <= 14400 && rottingTime - worldIn.getTotalWorldTime() > 9600)
									tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.rotting_3"));
								else if(rottingTime - worldIn.getTotalWorldTime() <= 9600 && rottingTime - worldIn.getTotalWorldTime() > 4800)
									tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.rotting_4"));
								else if(rottingTime - worldIn.getTotalWorldTime() <= 4800 && rottingTime - worldIn.getTotalWorldTime() > 0)
									tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.rotting_5"));
								else if(rottingTime - worldIn.getTotalWorldTime() <= 0)
									tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.rotten"));
							}
						} else {
							tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.status") + I18n.format("tooltip.bl.item_mob_anadia.smoked"));
						}

						tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.health", MathHelper.ceil(living.getHealth()), MathHelper.ceil((living.getMaxHealth()))));
						tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.size", ((EntityAnadia) living).getFishSize()));
						tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.speed", (living.getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getAttributeValue())));
						tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.strength", (Math.floor(((EntityAnadia) living).getStrengthMods() + 0.5D))));
						tooltip.add(I18n.format("tooltip.bl.item_mob_anadia.stamina", ((EntityAnadia) living).getStaminaMods()));
					}
				} else {
					tooltip.add(I18n.format("tooltip.bl.item_mob.health", MathHelper.ceil(living.getHealth() / 2), MathHelper.ceil(living.getMaxHealth() / 2)));
				}
			}
		}
	}

	@Override
	@SideOnly(Side.CLIENT)
	public int getColorMultiplier(ItemStack stack, int tintIndex) {

		if(stack.getTagCompound() != null && stack.getTagCompound().hasKey("Entity", Constants.NBT.TAG_COMPOUND)) {

			// smoked
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") == 0)
				return 0x747479;

			// rotten
			if (stack.getTagCompound().getCompoundTag("Entity").hasKey("rottingTime")) {
				long rottingTime = stack.getTagCompound().getCompoundTag("Entity").getLong("rottingTime");
				if (rottingTime - Minecraft.getMinecraft().world.getTotalWorldTime() <= 0)
					return 0x5FB050;
			}

			// silver
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") == 3)
				return 0xC2B3DB;

			// purple
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") == 4)
				return 0x714147;

			// green
			if(stack.getTagCompound().getCompoundTag("Entity").getByte("fishColour") == 5)
				return 0x415432;
		}

		return 0x717A51; //default to base/brown
	}
}

